def ensure_dir(p):
    os.makedirs(p, exist_ok=True)

def norm(s):
    return re.sub(r'[^a-z0-9]+', '', str(s).strip().lower())

def find_fields(table):
    fields = [f.name for f in arcpy.ListFields(table)]
    fmap = {norm(f): f for f in fields}
    x = None; y = None; z = None
    # likely variants for survey E/N/Z
    x_candidates = ['e','east','easting','x','coorde','eastings']
    y_candidates = ['n','north','northing','y','coordn','northings']
    z_candidates = ['z','rl','elev','elevation','level','height','reducedlevel']
    for c in x_candidates:
        if c in fmap:
            x = fmap[c]; break
    for c in y_candidates:
        if c in fmap:
            y = fmap[c]; break
    for c in z_candidates:
        if c in fmap:
            z = fmap[c]; break
    # fallback fuzzy contains
    if not x:
        for f in fields:
            lf = f.lower()
            if 'east' in lf or lf in ['e','x']:
                x = f; break
    if not y:
        for f in fields:
            lf = f.lower()
            if 'north' in lf or lf in ['n','y']:
                y = f; break
    if not z:
        for f in fields:
            lf = f.lower()
            if lf == 'z' or 'elev' in lf or 'level' in lf or 'height' in lf or lf == 'rl':
                z = f; break
    return fields, x, y, z

def excel_sheet_name(xlsx_path):
    # ExcelToTable accepts sheet as positional argument; discover by workbook parse via Describe when possible.
    # Use first sheet by converting workbook to table view path via ExcelToTable with no sheet not possible, so inspect workbook through arcpy Excel table names.
    try:
        children = arcpy.Describe(xlsx_path).children
        if children:
            return children[0].name
    except:
        pass
    return None

def excel_to_csv(xlsx_path, csv_path, table_name):
    temp_gdb = os.path.join(project_root, 'scratch.gdb')
    if not arcpy.Exists(temp_gdb):
        arcpy.management.CreateFileGDB(project_root, 'scratch.gdb')
    out_table = os.path.join(temp_gdb, os.path.splitext(os.path.basename(csv_path))[0] + '_tbl')
    if arcpy.Exists(out_table):
        arcpy.management.Delete(out_table)
    if table_name:
        arcpy.conversion.ExcelToTable(xlsx_path, out_table, table_name)
    else:
        arcpy.conversion.ExcelToTable(xlsx_path, out_table)
    fields = [f.name for f in arcpy.ListFields(out_table) if f.type not in ('OID','Geometry','Blob','Raster')]
    with open(csv_path, 'w', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        w.writerow(fields)
        with arcpy.da.SearchCursor(out_table, fields) as cur:
            for row in cur:
                w.writerow(list(row))
    return out_table

def create_points_from_table(table, out_fc):
    fields, x_field, y_field, z_field = find_fields(table)
    if not (x_field and y_field and z_field):
        raise RuntimeError(f'Missing usable E/N/Z fields in {table}. Fields: {fields}')
    if arcpy.Exists(out_fc):
        arcpy.management.Delete(out_fc)
    gdb = os.path.dirname(out_fc)
    name = os.path.basename(out_fc)
    arcpy.management.CreateFeatureclass(gdb, name, 'POINT', spatial_reference=sr)
    arcpy.management.AddField(out_fc, 'SRC_OID', 'LONG')
    arcpy.management.AddField(out_fc, 'ZVAL', 'DOUBLE')
    inserted = 0
    with arcpy.da.SearchCursor(table, ['OID@', x_field, y_field, z_field]) as sc, \
         arcpy.da.InsertCursor(out_fc, ['SRC_OID', 'ZVAL', 'SHAPE@XY']) as ic:
        for oid, xv, yv, zv in sc:
            try:
                x = float(str(xv).replace(',', '').strip())
                y = float(str(yv).replace(',', '').strip())
                z = float(str(zv).replace(',', '').strip())
            except:
                continue
            ic.insertRow((oid, z, (x, y)))
            inserted += 1
    if inserted == 0:
        raise RuntimeError(f'No usable numeric E/N/Z rows found in {table}')
    return inserted, x_field, y_field, z_field

def derive_boundary_polygon(cad_gdb, out_poly):
    arcpy.conversion.CADToGeodatabase(boundary_dwg, cad_gdb, 'cadimport', 1000, sr)
    poly_fc = os.path.join(cad_gdb, 'cadimport', 'Polygon')
    pline_fc = os.path.join(cad_gdb, 'cadimport', 'Polyline')
    candidates = []
    if arcpy.Exists(poly_fc) and int(arcpy.management.GetCount(poly_fc)[0]) > 0:
        candidates.append(poly_fc)
    if arcpy.Exists(pline_fc) and int(arcpy.management.GetCount(pline_fc)[0]) > 0:
        candidates.append(pline_fc)
    if not candidates:
        raise RuntimeError('No polygon/polyline entities found in DWG boundary import')
    if arcpy.Exists(out_poly):
        arcpy.management.Delete(out_poly)
    # Prefer existing polygons; otherwise convert closed polylines to polygons
    if poly_fc in candidates:
        arcpy.management.CopyFeatures(poly_fc, out_poly)
    else:
        arcpy.management.FeatureToPolygon(pline_fc, out_poly)
    # Keep largest polygon as analysis boundary
    area_field = '__A'
    if area_field not in [f.name for f in arcpy.ListFields(out_poly)]:
        arcpy.management.AddField(out_poly, area_field, 'DOUBLE')
    arcpy.management.CalculateField(out_poly, area_field, '!shape.area!', 'PYTHON3')
    oid_field = arcpy.Describe(out_poly).OIDFieldName
    max_oid = None; max_a = -1
    with arcpy.da.SearchCursor(out_poly, [oid_field, area_field]) as cur:
        for oid, a in cur:
            if a is not None and a > max_a:
                max_a = a; max_oid = oid
    lyr = 'boundary_lyr'
    arcpy.management.MakeFeatureLayer(out_poly, lyr, f'{arcpy.AddFieldDelimiters(out_poly, oid_field)} = {max_oid}')
    tmp = out_poly + '_single'
    if arcpy.Exists(tmp):
        arcpy.management.Delete(tmp)
    arcpy.management.CopyFeatures(lyr, tmp)
    arcpy.management.Delete(out_poly)
    arcpy.management.Rename(tmp, out_poly)
    return out_poly

def run_idw(points_fc, z_field, out_raster, boundary_fc):
    ext = arcpy.Describe(boundary_fc).extent
    arcpy.env.extent = ext
    arcpy.env.mask = boundary_fc
    arcpy.env.outputCoordinateSystem = sr
    arcpy.env.cellSize = max((ext.width + ext.height) / 500.0, 1.0)
    try:
        if arcpy.Exists(out_raster):
            arcpy.management.Delete(out_raster)
    except:
        pass
    try:
        idw = arcpy.sa.Idw(points_fc, z_field)
        idw.save(out_raster)
    except arcpy.ExecuteError:
        msg = arcpy.GetMessages(2)
        if '010092' in msg or 'Invalid output extent' in msg:
            # repair extent: slightly expand, keep mask
            ext2 = arcpy.Extent(ext.XMin - 1, ext.YMin - 1, ext.XMax + 1, ext.YMax + 1)
            arcpy.env.extent = ext2
            idw = arcpy.sa.Idw(points_fc, z_field)
            idw.save(out_raster)
        else:
            raise

def add_to_map(aprx_path, datasets):
    try:
        aprx = arcpy.mp.ArcGISProject(aprx_path)
        m = aprx.listMaps()[0]
        existing = {lyr.name for lyr in m.listLayers()}
        for ds in datasets:
            if arcpy.Exists(ds):
                name = os.path.basename(ds)
                if name not in existing:
                    m.addDataFromPath(ds)
        aprx.save()
    except:
        pass

