    pre_tbl = excel_to_csv(pre_xlsx, pre_csv, pre_sheet)
    post_tbl = excel_to_csv(post_xlsx, post_csv, post_sheet)

    # Also import Excel tables into geodatabase for robust OID handling
    pre_gdb_tbl = os.path.join(gdb, 'pre_tbl')
    post_gdb_tbl = os.path.join(gdb, 'post_tbl')
    if arcpy.Exists(pre_gdb_tbl): arcpy.management.Delete(pre_gdb_tbl)
    if arcpy.Exists(post_gdb_tbl): arcpy.management.Delete(post_gdb_tbl)
    if pre_sheet:
        arcpy.conversion.ExcelToTable(pre_xlsx, pre_gdb_tbl, pre_sheet)
    else:
        arcpy.conversion.ExcelToTable(pre_xlsx, pre_gdb_tbl)
    if post_sheet:
        arcpy.conversion.ExcelToTable(post_xlsx, post_gdb_tbl, post_sheet)
