    pre_inserted, pre_x, pre_y, pre_z = create_points_from_table(pre_gdb_tbl, pre_pts)
    post_inserted, post_x, post_y, post_z = create_points_from_table(post_gdb_tbl, post_pts)

    # Boundary from DWG polygon/polyline
    boundary_fc = os.path.join(gdb, 'boundary_polygon')
    derive_boundary_polygon(cad_gdb, boundary_fc)

    # IDW rasters
    pre_idw = os.path.join(gdb, 'PRE_IDW')
