    run_idw(pre_pts, 'ZVAL', pre_idw, boundary_fc)
    run_idw(post_pts, 'ZVAL', post_idw, boundary_fc)

    # CutFill
    arcpy.env.extent = arcpy.Describe(boundary_fc).extent
    arcpy.env.mask = boundary_fc
    arcpy.env.outputCoordinateSystem = sr
    cutfill = os.path.join(gdb, 'CutFill')
    if arcpy.Exists(cutfill):
        arcpy.management.Delete(cutfill)
    try:
        arcpy.sa.CutFill(pre_idw, post_idw).save(cutfill)
    except arcpy.ExecuteError:
        msg = arcpy.GetMessages(2)
        if '010092' in msg or 'Invalid output extent' in msg:
            ext = arcpy.Describe(boundary_fc).extent
            arcpy.env.extent = arcpy.Extent(ext.XMin - 1, ext.YMin - 1, ext.XMax + 1, ext.YMax + 1)
            arcpy.sa.CutFill(pre_idw, post_idw).save(cutfill)
        else:
            raise

    # Summarize cut/fill by raster cell values * cell area
    desc = arcpy.Describe(cutfill)
    cell_w = desc.meanCellWidth
    cell_h = desc.meanCellHeight
    cell_area = float(cell_w) * float(cell_h)
    total_volume = 0.0
    cut_volume = 0.0
    fill_volume = 0.0
    total_area = 0.0
    arr_fields = ['VALUE', 'COUNT']
    with arcpy.da.SearchCursor(cutfill, arr_fields) as cur:
        for val, cnt in cur:
            if val is None or cnt is None:
                continue
            vol = float(val) * float(cnt) * cell_area
            area = float(cnt) * cell_area
            total_volume += vol
            total_area += area
            if vol < 0:
                cut_volume += vol
            else:
                fill_volume += vol

    # Export CSV result
    with open(output_csv, 'w', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        w.writerow(['Metric', 'Value', 'Units'])
        w.writerow(['Pre_Point_Count', pre_inserted, 'points'])
        w.writerow(['Post_Point_Count', post_inserted, 'points'])
        w.writerow(['Analysis_Area', total_area, 'square_meters'])
        w.writerow(['Cut_Volume', cut_volume, 'cubic_meters'])
        w.writerow(['Fill_Volume', fill_volume, 'cubic_meters'])
        w.writerow(['Net_Volume_Post_minus_Pre', total_volume, 'cubic_meters'])
        w.writerow(['Coordinate_System', sr.name, ''])
        w.writerow(['Pre_CSV_Copy', pre_csv, ''])
        w.writerow(['Post_CSV_Copy', post_csv, ''])
        w.writerow(['Boundary_DWG', boundary_dwg, ''])

    add_to_map(aprx_path, [boundary_fc, pre_pts, post_pts, pre_idw, post_idw, cutfill])

    print(f'RESULT_PRE_POINT_COUNT: {pre_inserted}')
    print(f'RESULT_POST_POINT_COUNT: {post_inserted}')
    print(f'RESULT_ANALYSIS_AREA_SQM: {total_area}')
    print(f'RESULT_CUT_VOLUME_CUM: {cut_volume}')
    print(f'RESULT_FILL_VOLUME_CUM: {fill_volume}')
    print(f'RESULT_NET_VOLUME_CUM: {total_volume}')
    print(f'RESULT_OUTPUT_CSV: {output_csv}')
    print(f'RESULT_PRE_CSV_COPY: {pre_csv}')
    print(f'RESULT_POST_CSV_COPY: {post_csv}')
